mapper.select:
/* 회의록 정보 조회 */ select a.id id , a.meeting_owner_id meetingOwnerId , a.subject subject , a.subject_code subjectCode , a.content content , to_char(a.meeting_date,'yyyy-mm-dd hh24:mi') meetingDate , to_char(a.created_at,'yyyy-mm-dd hh24:mi') createdAt , coalesce(b.id, 0) file_id , b.audio_file_path audioFilePath , b.transcript_file_path transcriptFilePath , b.summary_file_path summaryFilePath , b.analyze_status analyzeStatus , ( select string_agg(ar_codes.analysis_type_code, ',' order by ar_codes.analysis_type_code) from ( select distinct ar.analysis_type_code from analysis_result ar where ar.file_id = b.id ) ar_codes ) analysisTypeCodes , ( select string_agg( ar_history.analysis_type_code || '|' || to_char(ar_history.analyzed_at, 'yyyy-mm-dd hh24:mi'), ',' order by ar_history.analyzed_at desc ) from analysis_result ar_history where ar_history.file_id = b.id ) analysisHistory from meeting_minutes a left outer join file_attach b on a.id = b.target_id
AND lower(a.meeting_owner_id) LIKE '%' || lower(#{ownerSearch}) || '%'
AND a.meeting_owner_id = #{loginEmail}
AND a.subject LIKE '%' || #{subject} || '%'
AND a.created_at >= to_timestamp(#{startDate}, 'YYYY-MM-DD')
AND a.created_at < to_timestamp(#{endDate}, 'YYYY-MM-DD') + interval '1 day'
AND EXISTS ( SELECT 1 FROM analysis_result ar WHERE ar.file_id = b.id AND ar.analysis_type_code = #{analysisType} )
order by ( select max(ar_sort.analyzed_at) from analysis_result ar_sort where ar_sort.file_id = b.id ) desc nulls last, a.created_at desc, a.id desc
limit #{limit}
offset #{offset}
